79	// ── CRO Pillars ──────────────────────────────────────────────
80	
81	export type CroPillar =
82	  | "value_proposition"
83	  | "cta_effectiveness"
84	  | "trust_signals"
85	  | "visual_hierarchy"
86	  | "mobile_experience"
87	  | "content_copy"
