43	  plan: PlanType;
44	  scans_used: number;
45	  scan_limit: number;
46	  role: UserRole;
47	  is_banned: boolean;
48	  dodo_customer_id: string | null;
49	  dodo_subscription_id: string | null;
50	  billing_cycle_end: string | null;
