1	/**
2	 * analyze-url — Edge Function (Orchestrator)
3	 *
4	 * Full CRO audit pipeline for a given URL.
5	 *
6	 * Pipeline:
7	 *   1. Auth + scan limit check
8	 *   2. Create scan record (status: analyzing)
9	 *   3. Screenshot + DOM scrape (Railway service or dev fallback)
10	 *   4. Upload screenshot to Supabase Storage
11	 *   5. AI Vision Analysis (Claude + screenshot)
12	 *   6. AI Text Analysis (Claude + DOM content)
13	 *   7. PageSpeed Analysis (Google API)
14	 *   8. Score + Save (insert scan_results, update scan)
15	 *   9. Return scan ID
16	 *
17	 * Required env vars:
18	 *   SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY
19	 *   ANTHROPIC_API_KEY
20	 *   SCREENSHOT_SERVICE_URL (Railway service) — optional in dev
21	 *   SCREENSHOT_SERVICE_API_KEY — required if service URL is set
22	 *   PAGESPEED_API_KEY — Google Cloud API key
23	 *   SCREENSHOTONE_ACCESS_KEY — dev fallback screenshot service
24	 */
25	
26	import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
27	import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
28	import { buildVisionPrompt, buildTextPrompt, PageType } from "./prompts.ts";
29	import {
30	  calculateScoringOutput,
31	  sanitizeFinding,
32	  VisionAnalysisResult,
33	  TextAnalysisResult,
34	  PageSpeedResult,
35	  Finding,
36	} from "./scoring.ts";
37	
38	// ── CORS headers ──────────────────────────────────────────────
39	
40	const corsHeaders = {
41	  "Access-Control-Allow-Origin": "*",
42	  "Access-Control-Allow-Headers":
43	    "authorization, x-client-info, apikey, content-type",
44	  "Access-Control-Allow-Methods": "POST, OPTIONS",
45	};
46	
47	function corsResponse(body: unknown, status = 200) {
48	  return new Response(JSON.stringify(body), {
49	    status,
50	    headers: { ...corsHeaders, "Content-Type": "application/json" },
51	  });
52	}
53	
54	// ── DOM data shape from screenshot service ────────────────────
55	
56	interface DomData {
57	  headings: string[];
58	  cta_buttons: string[];
59	  images: Array<{ src: string; alt: string }>;
60	  meta_description: string;
61	  body_text: string;
62	  links: Array<{ text: string; href: string }>;
63	  forms: number;
64	  testimonials: string[];
65	  trust_badges: string[];
66	}
67	
68	interface ScreenshotServiceResponse {
69	  screenshot_base64: string;
70	  dom_data: DomData;
71	  page_title: string;
72	  favicon_url: string;
73	}
74	
75	// ── Main handler ──────────────────────────────────────────────
76	
77	serve(async (req: Request) => {
78	  // Preflight
79	  if (req.method === "OPTIONS") {
80	    return new Response("ok", { headers: corsHeaders });
81	  }
82	
83	  if (req.method !== "POST") {
84	    return corsResponse({ error: "Method not allowed" }, 405);
85	  }
86	
87	  // ── 1. Auth ─────────────────────────────────────────────────
88	  const authHeader = req.headers.get("Authorization");
89	  if (!authHeader?.startsWith("Bearer ")) {
90	    return corsResponse({ error: "Missing authorization header" }, 401);
91	  }
92	  const token = authHeader.replace("Bearer ", "").trim();
93	
94	  const supabase = createClient(
95	    Deno.env.get("SUPABASE_URL") ?? "",
96	    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "",
97	  );
98	
99	  const { data: { user }, error: authError } = await supabase.auth.getUser(token);
100	  if (!user || authError) {
101	    return corsResponse({ error: "Unauthorized" }, 401);
102	  }
103	
104	  // ── 2. Parse request body ────────────────────────────────────
105	  let url: string;
106	  let pageType: PageType;
107	  let existingScanId: string | undefined;
108	  try {
109	    const body = await req.json();
110	    url = body.url;
111	    pageType = body.page_type ?? "other";
112	    existingScanId = typeof body.scan_id === "string" ? body.scan_id : undefined;
113	    if (!url || typeof url !== "string") {
114	      return corsResponse({ error: "url is required" }, 400);
115	    }
116	    // Normalize URL
117	    if (!url.startsWith("http://") && !url.startsWith("https://")) {
118	      url = `https://${url}`;
119	    }
120	    new URL(url); // validate format — throws if invalid
121	  } catch (_e) {
122	    return corsResponse({ error: "Invalid request body or URL" }, 400);
123	  }
124	
125	  // ── 3. Check scan limit ──────────────────────────────────────
126	  const { data: allowed, error: limitError } = await supabase.rpc(
127	    "increment_scan_usage",
128	    { user_uuid: user.id },
129	  );
130	  if (limitError || !allowed) {
131	    // Clean up the pending scan row the frontend already created
132	    if (existingScanId) {
133	      await supabase
134	        .from("scans")
135	        .update({ status: "failed", error_message: "Scan limit reached" })
136	        .eq("id", existingScanId)
137	        .eq("user_id", user.id);
138	    }
139	    return corsResponse(
140	      { error: "Scan limit reached. Upgrade your plan to continue." },
141	      429,
142	    );
143	  }
144	
145	  // ── 4. Use existing scan record or create a new one ──────────
146	  let scanId: string;
147	
148	  if (existingScanId) {
149	    // Update the frontend-created pending scan to analyzing
150	    const { error: updateError } = await supabase
151	      .from("scans")
152	      .update({ status: "analyzing", device: "both" })
153	      .eq("id", existingScanId)
154	      .eq("user_id", user.id);
155	
156	    if (updateError) {
157	      console.error("Failed to update scan record:", updateError);
158	      return corsResponse({ error: "Failed to initiate scan" }, 500);
159	    }
160	    scanId = existingScanId;
161	  } else {
162	    // Fallback: create scan record (backwards compatibility / direct API calls)
163	    const { data: scan, error: scanInsertError } = await supabase
164	      .from("scans")
165	      .insert({
166	        user_id: user.id,
167	        url,
168	        page_type: pageType,
169	        status: "analyzing",
170	        device: "both",
171	      })
172	      .select("id")
173	      .single();
174	
175	    if (scanInsertError || !scan) {
176	      console.error("Failed to create scan record:", scanInsertError);
177	      return corsResponse({ error: "Failed to initiate scan" }, 500);
178	    }
179	    scanId = scan.id;
180	  }
181	
182	  // All subsequent errors must update scan status to failed
183	  const failScan = async (message: string) => {
184	    await supabase
185	      .from("scans")
186	      .update({ status: "failed", error_message: message })
187	      .eq("id", scanId);
188	  };
189	
190	  try {
191	    // ── 5. Screenshot + Scrape ─────────────────────────────────
192	    let screenshotData: ScreenshotServiceResponse;
193	    try {
194	      screenshotData = await captureScreenshot(url);
195	    } catch (e) {
196	      const msg = e instanceof Error ? e.message : "Screenshot capture failed";
197	      await failScan(msg);
198	      return corsResponse({ error: msg }, 500);
199	    }
200	
201	    // ── 6. Upload screenshot ───────────────────────────────────
202	    let screenshotUrl: string | null = null;
203	    if (screenshotData.screenshot_base64) {
204	      try {
205	        screenshotUrl = await uploadScreenshot(
206	          supabase,
207	          screenshotData.screenshot_base64,
208	          scanId,
209	        );
210	      } catch (e) {
211	        // Non-fatal — scan continues without screenshot
212	        console.warn("Screenshot upload failed:", e);
213	      }
214	    }
215	
216	    // Update scan with page metadata from screenshot service
217	    await supabase
218	      .from("scans")
219	      .update({
220	        page_title: screenshotData.page_title || null,
221	        favicon_url: screenshotData.favicon_url || null,
222	        screenshot_url: screenshotUrl,
223	      })
224	      .eq("id", scanId);
225	
226	    // ── 7. AI Vision Analysis ──────────────────────────────────
227	    let visionResult: VisionAnalysisResult;
228	    try {
229	      visionResult = await runVisionAnalysis(
230	        screenshotData.screenshot_base64,
231	        pageType,
232	      );
233	    } catch (e) {
234	      const msg = e instanceof Error ? e.message : "AI vision analysis failed";
235	      await failScan(msg);
236	      return corsResponse({ error: msg }, 500);
237	    }
238	
239	    // ── 8. AI Text Analysis ────────────────────────────────────
240	    let textResult: TextAnalysisResult;
241	    try {
242	      textResult = await runTextAnalysis(screenshotData.dom_data, pageType);
243	    } catch (e) {
244	      const msg = e instanceof Error ? e.message : "AI text analysis failed";
245	      await failScan(msg);
246	      return corsResponse({ error: msg }, 500);
247	    }
248	
249	    // ── 9. PageSpeed Analysis ──────────────────────────────────
250	    let pageSpeedResult: PageSpeedResult;
251	    try {
252	      pageSpeedResult = await runPageSpeedAnalysis(url);
253	    } catch (e) {
254	      // Non-fatal — use fallback score
255	      console.warn("PageSpeed analysis failed, using fallback:", e);
256	      pageSpeedResult = buildPageSpeedFallback();
257	    }
258	
259	    // ── 10. Score + Save ───────────────────────────────────────
260	    const scoring = calculateScoringOutput(
261	      visionResult,
262	      textResult,
263	      pageSpeedResult,
264	      pageType,
265	      scanId,
266	    );
267	
268	    // Insert one row per pillar into scan_results
269	    const scanResultRows = scoring.pillar_results.map((pr) => ({
270	      scan_id: scanId,
271	      pillar: pr.pillar,
272	      score: pr.score,
273	      weight: pr.weight,
274	      benchmark: pr.benchmark,
275	      findings: pr.findings,
276	    }));
277	
278	    const { error: resultsError } = await supabase
279	      .from("scan_results")
280	      .insert(scanResultRows);
281	
282	    if (resultsError) {
283	      console.error("Failed to insert scan_results:", resultsError);
284	      await failScan("Failed to save analysis results");
285	      return corsResponse({ error: "Failed to save results" }, 500);
286	    }
287	
288	    // Update scan to completed
289	    const { error: updateError } = await supabase
290	      .from("scans")
291	      .update({
292	        status: "completed",
293	        overall_score: scoring.overall_score,
294	        issues_found: scoring.issues_found,
295	        critical_issues: scoring.critical_issues,
296	        warnings: scoring.warnings,
297	        quick_wins: scoring.quick_wins,
298	        completed_at: new Date().toISOString(),
299	      })
300	      .eq("id", scanId);
301	
302	    if (updateError) {
303	      console.error("Failed to update scan status:", updateError);
304	      // Results are saved — don't fail the whole scan
305	    }
306	
307	    // ── 11. Send scan complete email (fire-and-forget) ─────────────
308	    try {
309	      // Fetch user profile for name and email
310	      const [profileRes, emailRes] = await Promise.all([
311	        supabase
312	          .from("profiles")
313	          .select("full_name, company_name")
314	          .eq("id", user.id)
315	          .single(),
