763	
764	  // Extract Core Web Vitals in milliseconds
765	  const lcpMs: number = audits["largest-contentful-paint"]?.numericValue ?? 0;
766	  const clsVal: number = audits["cumulative-layout-shift"]?.numericValue ?? 0;
767	  const tbtMs: number = audits["total-blocking-time"]?.numericValue ?? 0;
768	  const fcpMs: number = audits["first-contentful-paint"]?.numericValue ?? 0;
