814	        "Technical",
815	      ));
816	    }
817	  }
818	
819	  // CLS findings
820	  if (clsVal > 0) {
821	    if (clsVal > 0.25) {
822	      findings.push(buildPerfFinding(
823	        "f_pp_cls",
