992	
993	function extractJsonFromText(text: string): string {
994	  // Strip markdown code blocks if present
995	  const codeBlockMatch = text.match(/```(?:json)?\s*([\s\S]*?)```/);
996	  if (codeBlockMatch) return codeBlockMatch[1].trim();
997	
998	  // Find first { and last }
999	  const start = text.indexOf("{");
1000	  const end = text.lastIndexOf("}");
1001	  if (start !== -1 && end !== -1 && end > start) {
1002	    return text.slice(start, end + 1);
1003	  }
1004	
1005	  return text.trim();
1006	}
1007	
1008	function parseAndSanitizeVisionResult(rawText: string): VisionAnalysisResult {
1009	  let parsed: Record<string, unknown>;
1010	  try {
1011	    parsed = JSON.parse(extractJsonFromText(rawText));
1012	  } catch (_e) {
1013	    console.error("Failed to parse vision AI response:", rawText.slice(0, 500));
1014	    // Return safe defaults
1015	    return buildDefaultVisionResult();
1016	  }
1017	
1018	  return {
1019	    visual_hierarchy: sanitizePillarResult(
1020	      parsed.visual_hierarchy as Record<string, unknown>,
1021	      "vh",
1022	    ),
1023	    cta_effectiveness: sanitizePillarResult(
1024	      parsed.cta_effectiveness as Record<string, unknown>,
1025	      "ct",
1026	    ),
1027	    trust_signals: sanitizePillarResult(
1028	      parsed.trust_signals as Record<string, unknown>,
1029	      "ts",
1030	    ),
1031	    mobile_experience: sanitizePillarResult(
1032	      parsed.mobile_experience as Record<string, unknown>,
1033	      "me",
1034	    ),
1035	  };
1036	}
1037	
1038	function parseAndSanitizeTextResult(rawText: string): TextAnalysisResult {
1039	  let parsed: Record<string, unknown>;
1040	  try {
1041	    parsed = JSON.parse(extractJsonFromText(rawText));
1042	  } catch (_e) {
1043	    console.error("Failed to parse text AI response:", rawText.slice(0, 500));
1044	    return buildDefaultTextResult();
1045	  }
1046	
1047	  return {
1048	    value_proposition: sanitizePillarResult(
1049	      parsed.value_proposition as Record<string, unknown>,
1050	      "vp",
1051	    ),
1052	    content_copy: sanitizePillarResult(
1053	      parsed.content_copy as Record<string, unknown>,
1054	      "cc",
1055	    ),
1056	    cta_effectiveness: parsed.cta_effectiveness
1057	      ? sanitizePillarResult(
1058	          parsed.cta_effectiveness as Record<string, unknown>,
1059	          "ct_copy",
1060	        )
1061	      : undefined,
1062	  };
1063	}
1064	
1065	function sanitizePillarResult(
1066	  raw: Record<string, unknown> | undefined,
1067	  prefix: string,
1068	): { score: number; findings: Finding[] } {
1069	  if (!raw || typeof raw !== "object") {
1070	    return { score: 50, findings: [] };
1071	  }
1072	
1073	  const score = typeof raw.score === "number"
1074	    ? Math.max(0, Math.min(100, Math.round(raw.score)))
1075	    : 50;
1076	
1077	  const rawFindings = Array.isArray(raw.findings) ? raw.findings : [];
1078	  const findings: Finding[] = rawFindings
1079	    .filter((f): f is Record<string, unknown> => f !== null && typeof f === "object")
1080	    .map((f, i) =>
1081	      sanitizeFinding(f, `f_${prefix}_${String(i + 1).padStart(2, "0")}`)
1082	    );
1083	
1084	  return { score, findings };
1085	}
1086	
1087	function buildDefaultVisionResult(): VisionAnalysisResult {
1088	  const defaultPillar = { score: 50, findings: [] };
1089	  return {
1090	    visual_hierarchy: defaultPillar,
1091	    cta_effectiveness: defaultPillar,
1092	    trust_signals: defaultPillar,
1093	    mobile_experience: defaultPillar,
1094	  };
1095	}
1096	
1097	function buildDefaultTextResult(): TextAnalysisResult {
1098	  const defaultPillar = { score: 50, findings: [] };
1099	  return {
1100	    value_proposition: defaultPillar,
1101	    content_copy: defaultPillar,
1102	  };
1103	}
