1111	function decodeHtmlEntities(text: string): string {
1112	  return text
1113	    .replace(/&amp;/g, "&")
1114	    .replace(/&lt;/g, "<")
1115	    .replace(/&gt;/g, ">")
1116	    .replace(/&quot;/g, '"')
1117	    .replace(/&#039;/g, "'")
1118	    .replace(/&apos;/g, "'");
1119	}
