              content: "Analyze the page content provided in the system prompt and return the copy rewrite JSON array.",
            },
          ],
        }),
      });

      if (copyRes.ok) {
        const copyData = await copyRes.json();
        const rawCopyText: string = copyData.content?.[0]?.text ?? "[]";

        // Extract JSON array from response
        let parsedRewrites: unknown;
        try {
          const codeBlockMatch = rawCopyText.match(/```(?:json)?\s*([\s\S]*?)```/);
          const jsonText = codeBlockMatch
            ? codeBlockMatch[1].trim()
            : rawCopyText.slice(
                rawCopyText.indexOf("["),
                rawCopyText.lastIndexOf("]") + 1,
              );
          parsedRewrites = JSON.parse(jsonText);
        } catch (_parseErr) {
          console.warn("Failed to parse copy rewrite response:", rawCopyText.slice(0, 300));
