import { useQuery } from "@tanstack/react-query";
import supabase from "@/lib/supabase";
import type { CopyRewrite } from "@/types";

export function useCopyRewrites(scanId: string) {
  return useQuery({
    queryKey: ["copy-rewrites", scanId],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("copy_rewrites")
        .select("*")
        .eq("scan_id", scanId)
        .order("created_at", { ascending: true });
      if (error) throw error;
      return (data ?? []) as CopyRewrite[];
    },
    enabled: !!scanId,
  });
}

import { useState, useRef, useEffect } from "react";
import { motion } from "framer-motion";
import { Copy, Check } from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";
import type { CopyRewrite, CopyRewriteElementType } from "@/types";

// ── Element type label + color map ────────────────────────────

const ELEMENT_TYPE_CONFIG: Record<
  CopyRewriteElementType,
  { label: string; className: string }
> = {
  headline: {
    label: "Headline",
    className: "bg-violet-100 text-violet-700 border-violet-200",
  },
  subheadline: {
    label: "Subheadline",
    className: "bg-indigo-100 text-indigo-700 border-indigo-200",
  },
  cta: {
    label: "CTA",
    className: "bg-orange-100 text-orange-700 border-orange-200",
  },
  value_prop: {
    label: "Value Prop",
    className: "bg-blue-100 text-blue-700 border-blue-200",
  },
  body_copy: {
    label: "Body Copy",
    className: "bg-slate-100 text-slate-700 border-slate-200",
  },
};

// ── Copy inline button ─────────────────────────────────────────

function CopyInline({ text }: { text: string }) {
  const [copied, setCopied] = useState(false);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(
    () => () => {
      if (timerRef.current) clearTimeout(timerRef.current);
    },
    [],
  );

  const handleCopy = async () => {
    if (timerRef.current) clearTimeout(timerRef.current);
    try {
      await navigator.clipboard.writeText(text);
    } catch {
      /* clipboard API unavailable */
    }
    setCopied(true);
    timerRef.current = setTimeout(() => setCopied(false), 2000);
  };

  return (
    <button
      onClick={handleCopy}
      className={cn(
        "inline-flex items-center gap-1 rounded-md px-2 py-0.5 text-2xs font-medium border transition-all",
        copied
          ? "bg-green-50 text-green-600 border-green-200"
          : "bg-card text-muted-foreground border-border/50 hover:bg-muted/40 hover:text-foreground",
      )}
    >
      {copied ? (
        <>
          <Check className="h-2.5 w-2.5" />
          Copied
        </>
      ) : (
        <>
          <Copy className="h-2.5 w-2.5" />
          Copy
        </>
      )}
    </button>
  );
}

// ── CopyRewriteCard ────────────────────────────────────────────

interface CopyRewriteCardProps {
  rewrite: CopyRewrite;
}

export function CopyRewriteCard({ rewrite }: CopyRewriteCardProps) {
  const typeConfig =
    ELEMENT_TYPE_CONFIG[rewrite.element_type] ?? ELEMENT_TYPE_CONFIG.body_copy;

  return (
    <motion.div
      initial={{ opacity: 0, y: 8 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.25, ease: "easeOut" }}
    >
      <Card className="border-border/50 shadow-soft overflow-hidden">
        <CardContent className="p-0">
          {/* Element type badge row */}
          <div className="flex items-center gap-2 border-b border-border/40 px-4 py-2.5">
            <Badge
              variant="outline"
              className={cn("text-2xs font-semibold uppercase tracking-wide px-2 py-0.5", typeConfig.className)}
            >
              {typeConfig.label}
            </Badge>
            {rewrite.impact && (
              <span className="text-xs text-muted-foreground ml-auto truncate max-w-[280px]">
                {rewrite.impact}
              </span>
            )}
          </div>

          {/* Side-by-side copy comparison */}
          <div className="grid grid-cols-1 gap-0 sm:grid-cols-2">
            {/* Current copy */}
            <div className="border-b border-border/40 p-4 sm:border-b-0 sm:border-r">
              <p className="mb-2 text-2xs font-semibold uppercase tracking-widest text-red-500">
                Current
              </p>
              <div className="rounded-lg bg-red-50 border border-red-100 p-3">
                <p className="text-sm text-slate-600 leading-relaxed line-through decoration-red-400/60">
                  {rewrite.original}
                </p>
              </div>
            </div>

            {/* Suggested copy */}
            <div className="p-4">
              <div className="mb-2 flex items-center justify-between">
                <p className="text-2xs font-semibold uppercase tracking-widest text-emerald-600">
                  Suggested
                </p>
                <CopyInline text={rewrite.suggested} />
              </div>
              <div className="rounded-lg bg-emerald-50 border border-emerald-100 p-3">
                <p className="text-sm text-slate-700 font-medium leading-relaxed">
                  {rewrite.suggested}
                </p>
              </div>
            </div>
          </div>

          {/* Reasoning */}
          <div className="border-t border-border/40 px-4 py-3">
            <p className="text-xs text-muted-foreground leading-relaxed">
              <span className="font-semibold text-foreground/70">Why this works: </span>
              {rewrite.reasoning}
            </p>
          </div>
        </CardContent>
      </Card>
    </motion.div>
  );
}

import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import { Skeleton } from "@/components/ui/skeleton";
import { useCopyRewrites } from "@/hooks/use-copy-rewrites";
import { CopyRewriteCard } from "./CopyRewriteCard";
import type { CopyRewrite, CopyRewriteElementType } from "@/types";

// ── Filter tab config ─────────────────────────────────────────

interface FilterTab {
  value: string;
  label: string;
  filter: (r: CopyRewrite) => boolean;
}

const FILTER_TABS: FilterTab[] = [
  { value: "all", label: "All", filter: () => true },
  {
    value: "headline",
    label: "Headlines",
    filter: (r) => r.element_type === "headline" || r.element_type === "subheadline",
  },
  {
    value: "cta",
    label: "CTAs",
    filter: (r) => r.element_type === "cta",
  },
  {
    value: "value_prop",
    label: "Value Props",
    filter: (r) => r.element_type === "value_prop",
  },
  {
    value: "body_copy",
    label: "Body",
    filter: (r) => r.element_type === "body_copy",
  },
];

// ── Loading skeleton ──────────────────────────────────────────

function CopyRewriteLoadingSkeleton() {
  return (
    <div className="space-y-4">
      {[1, 2, 3].map((i) => (
        <div key={i} className="overflow-hidden rounded-xl border border-border/50">
          <Skeleton className="h-10 w-full rounded-none" />
          <div className="grid grid-cols-2 gap-0">
            <div className="p-4 space-y-2 border-r border-border/40">
              <Skeleton className="h-3 w-16" />
              <Skeleton className="h-16 w-full rounded-lg" />
            </div>
            <div className="p-4 space-y-2">
              <Skeleton className="h-3 w-16" />
              <Skeleton className="h-16 w-full rounded-lg" />
            </div>
          </div>
          <div className="border-t border-border/40 p-4">
            <Skeleton className="h-3 w-full" />
            <Skeleton className="mt-1.5 h-3 w-3/4" />
          </div>
        </div>
      ))}
    </div>
  );
}

// ── Empty state ───────────────────────────────────────────────

function EmptyState() {
  return (
    <div className="flex flex-col items-center justify-center py-16 text-center">
      <div className="mb-3 flex h-12 w-12 items-center justify-center rounded-2xl bg-muted/50">
        <span className="text-2xl">✦</span>
      </div>
      <p className="text-sm font-medium text-foreground">No copy rewrites available</p>
      <p className="mt-1 max-w-xs text-xs text-muted-foreground">
        Copy rewrites are generated during the scan. This scan may not have produced rewrite suggestions.
      </p>
    </div>
  );
}

// ── CopyRewritePanel ──────────────────────────────────────────

interface CopyRewritePanelProps {
  scanId: string;
}

export function CopyRewritePanel({ scanId }: CopyRewritePanelProps) {
  const { data: rewrites = [], isLoading } = useCopyRewrites(scanId);

  if (isLoading) {
    return <CopyRewriteLoadingSkeleton />;
  }

  if (rewrites.length === 0) {
    return <EmptyState />;
  }

  return (
    <Tabs defaultValue="all">
      <TabsList className="mb-5 flex w-full flex-wrap gap-1 rounded-xl bg-muted/40 h-auto p-1">
        {FILTER_TABS.map((tab) => {
          const count =
            tab.value === "all" ? rewrites.length : rewrites.filter(tab.filter).length;
          return (
            <TabsTrigger
              key={tab.value}
              value={tab.value}
              disabled={tab.value !== "all" && count === 0}
              className="rounded-lg px-3 py-2 text-sm data-[state=active]:bg-white data-[state=active]:shadow-sm data-[state=active]:text-foreground disabled:opacity-40"
            >
              {tab.label}
              {count > 0 && (
                <span className="ml-1.5 rounded-full bg-muted px-1.5 py-0.5 text-xs text-foreground/70">
                  {count}
                </span>
              )}
            </TabsTrigger>
          );
        })}
      </TabsList>

      {FILTER_TABS.map((tab) => {
        const filtered = rewrites.filter(tab.filter);
        return (
          <TabsContent key={tab.value} value={tab.value}>
            {filtered.length > 0 ? (
              <div className="space-y-4">
                {filtered.map((rewrite) => (
                  <CopyRewriteCard key={rewrite.id} rewrite={rewrite} />
                ))}
              </div>
            ) : (
              <p className="py-8 text-center text-sm text-muted-foreground">
                No {tab.label.toLowerCase()} rewrites for this scan.
              </p>
            )}
          </TabsContent>
        );
      })}
    </Tabs>
  );
}

